//! Synthetic-stream tests: self-authored streams (tests/support/scenarios.rs) checked
//! against fingerprints of the FFmpeg 9.0.2 oracle's output (tests/data/synthetic.fp,
//! regenerated by research/d4/dca/make_fingerprints.sh), plus structural properties.
#![allow(clippy::needless_range_loop)]

mod support;
use support::{harness, scenarios, synth};

use triergon_codec_dca::{AudioFrame, DecodeError, Decoder, Packing};

fn scenario(name: &str) -> Vec<u8> {
    let mut meta = String::new();
    scenarios::scenarios(name, &mut meta).unwrap_or_else(|| panic!("scenario {name}"))
}

#[test]
fn scenarios_match_ffmpeg_fingerprints() {
    let fps = harness::parse_fingerprints(include_str!("data/synthetic.fp"));
    assert!(fps.len() >= 60);
    let mut failures = Vec::new();
    for fp in &fps {
        let bytes = scenario(&fp.name);
        let frames = harness::split(&bytes);
        let d = harness::decode_all(&frames);
        assert!(d.errors.is_empty(), "{}: {:?}", fp.name, d.errors);
        if let Err(e) = harness::check(fp, &d) {
            failures.push(e);
        }
    }
    assert!(failures.is_empty(), "{failures:#?}");
}

#[test]
fn packings_decode_identically() {
    let mut meta = String::new();
    let base = harness::decode_all(&harness::split(
        &scenarios::scenarios("pack_be16", &mut meta).unwrap(),
    ));
    assert!(base.frames == 8 && base.errors.is_empty());
    for p in ["pack_le16", "pack_be14", "pack_le14"] {
        let d = harness::decode_all(&harness::split(&scenario(p)));
        assert!(d.errors.is_empty(), "{p}: {:?}", d.errors);
        assert_eq!(d.planes, base.planes, "{p}");
    }
}

#[test]
fn layouts_follow_ffmpeg_native_order() {
    let cases: [(u8, &[&str]); 10] = [
        (0, &["FC", "LFE"]),
        (1, &["FL", "FR", "LFE"]),
        (2, &["FL", "FR", "LFE"]),
        (3, &["FL", "FR", "LFE"]),
        (4, &["FL", "FR", "LFE"]),
        (5, &["FL", "FR", "FC", "LFE"]),
        (6, &["FL", "FR", "LFE", "BC"]),
        (7, &["FL", "FR", "FC", "LFE", "BC"]),
        (8, &["FL", "FR", "LFE", "SL", "SR"]),
        (9, &["FL", "FR", "FC", "LFE", "SL", "SR"]),
    ];
    for (amode, want) in cases {
        let d = harness::decode_all(&harness::split(&scenario(&format!("amode{amode}"))));
        assert!(d.errors.is_empty());
        assert_eq!(d.speakers, want, "AMODE {amode}");
        assert_eq!(d.sample_rate, 48000);
    }
    let d = harness::decode_all(&harness::split(&scenario("nolfe")));
    assert_eq!(d.speakers, ["FL", "FR", "FC", "SL", "SR"]);
    let d = harness::decode_all(&harness::split(&scenario("x96_basic")));
    assert_eq!((d.sample_rate, d.planes[0].len() / d.frames), (96000, 1024));
}

#[test]
fn silence_decodes_to_zero() {
    let mut f = synth::Frame::new(9, 5, 16);
    f.lff = 2;
    for c in f.chans.iter_mut() {
        c.nsubs = 32;
        c.nvqsub = 32;
    }
    f.silent_subframe(2);
    let bytes: Vec<u8> = (0..3).flat_map(|_| synth::write_frame(&f)).collect();
    let d = harness::decode_all(&harness::split(&bytes));
    assert_eq!(d.frames, 3);
    assert!(
        d.planes
            .iter()
            .all(|p| p.len() == 1536 && p.iter().all(|&v| v == 0.0))
    );
}

#[test]
fn errors_are_typed() {
    let mut dec = Decoder::new();
    let mut out = AudioFrame::default();
    let bytes = scenario("basic");
    let frames = harness::split(&bytes);
    let good = frames[0];
    assert!(matches!(
        dec.decode(&good[..good.len() / 2], &mut out),
        Err(DecodeError::InvalidData(_))
    ));
    assert!(matches!(
        dec.decode(&[0u8; 64], &mut out),
        Err(DecodeError::InvalidData(_))
    ));
    assert!(matches!(
        dec.decode(&[], &mut out),
        Err(DecodeError::InvalidData(_))
    ));
    let am = scenario("amode10");
    assert!(matches!(
        dec.decode(harness::split(&am)[0], &mut out),
        Err(DecodeError::Unsupported(_))
    ));
    let short = scenario("short5");
    assert!(matches!(
        dec.decode(harness::split(&short)[0], &mut out),
        Err(DecodeError::Unsupported(_))
    ));
    // A failed frame must not poison the next good one.
    dec.decode(good, &mut out).expect("good frame after errors");
}

#[test]
fn corruption_never_panics() {
    let mut rng = scenarios::Rng(0x5EED);
    for name in [
        "huff",
        "x96_basic",
        "joint_huff",
        "adpcm",
        "pack_le14",
        "hfvq",
    ] {
        let bytes = scenario(name);
        let frames = harness::split(&bytes);
        let mut dec = Decoder::new();
        let mut out = AudioFrame::default();
        for i in 0..400 {
            let mut au = frames[i % frames.len()].to_vec();
            let flips = 1 + (rng.next() % 8) as usize;
            for _ in 0..flips {
                let pos = 6 + (rng.next() as usize) % (au.len() - 6);
                au[pos] ^= 1 << (rng.next() % 8);
            }
            if rng.next() % 5 == 0 {
                let cut = 6 + (rng.next() as usize) % (au.len() - 6);
                au.truncate(cut);
            }
            let _ = dec.decode(&au, &mut out);
            for p in &out.planes {
                assert_eq!(p.len(), out.samples_per_channel);
            }
        }
    }
}

#[test]
fn reset_restores_fresh_state() {
    let bytes = scenario("adpcm");
    let frames = harness::split(&bytes);
    let mut a = Decoder::new();
    let mut out_a = AudioFrame::default();
    for f in &frames {
        a.decode(f, &mut out_a).unwrap();
    }
    a.reset();
    a.decode(frames[0], &mut out_a).unwrap();
    let mut b = Decoder::new();
    let mut out_b = AudioFrame::default();
    b.decode(frames[0], &mut out_b).unwrap();
    assert_eq!(out_a.planes, out_b.planes);
}

#[test]
fn x96_invalid_revision_falls_back_to_core() {
    let d = harness::decode_all(&harness::split(&scenario("x96_rev9")));
    assert!(d.errors.is_empty());
    assert_eq!(d.sample_rate, 48000);
}

#[test]
fn packing_detection() {
    assert_eq!(
        Packing::detect(&[0x7F, 0xFE, 0x80, 0x01, 0, 0]),
        Some(Packing::Be16)
    );
    assert_eq!(
        Packing::detect(&[0xFE, 0x7F, 0x01, 0x80, 0, 0]),
        Some(Packing::Le16)
    );
    assert_eq!(
        Packing::detect(&[0x1F, 0xFF, 0xE8, 0x00, 0x07, 0xF0]),
        Some(Packing::Be14)
    );
    assert_eq!(
        Packing::detect(&[0xFF, 0x1F, 0x00, 0xE8, 0xF0, 0x07]),
        Some(Packing::Le14)
    );
    assert_eq!(Packing::detect(&[0x1F, 0xFF, 0xE8, 0x00, 0x00, 0x00]), None);
}

#[test]
fn failed_frame_is_dropped_without_disturbing_history() {
    let bytes = scenario("adpcm");
    let frames = harness::split(&bytes);
    // Corrupt the last DSYNC of frame 5 (the last 0xFFFF pair of its core data).
    let mut bad = frames[5].to_vec();
    let k = (0..bad.len() - 1)
        .rev()
        .find(|&j| bad[j] == 0xFF && bad[j + 1] == 0xFF)
        .unwrap();
    bad[k + 1] ^= 0x01;
    let mut with_bad: Vec<&[u8]> = frames.clone();
    with_bad[5] = &bad;
    let d1 = harness::decode_all(&with_bad);
    assert_eq!(d1.errors.len(), 1);
    let mut without: Vec<&[u8]> = frames.clone();
    without.remove(5);
    let d2 = harness::decode_all(&without);
    assert_eq!(d1.planes, d2.planes);
}
